import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            n_str = next(iterator)
            N = int(n_str)
        except StopIteration:
            break

        total = 0
        curr = 1

        while curr <= N:
            if curr > N:
                break

            bits = curr.bit_length()
            limit = (1 << bits) - 1

            if limit > N:
                limit = N

            count = limit - curr + 1

            if count % 2 == 0:
                pair_sum = (curr ^ (curr + count - 1)) * (count // 2)
                total += pair_sum
                curr = curr + count
            else:
                pair_count = count - 1
                pair_sum = (curr ^ (curr + pair_count - 1)) * (pair_count // 2)
                total += pair_sum
                last_val = curr + pair_count
                total += last_val ^ last_val
                curr = curr + count

        results.append(str(total))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
